-- V014__seed_cmt_apu_details.sql
-- Deterministic CMT APU details parsed from the IESS Tulcán XLSX workbook.
-- Workbook sheets are matched to budget rows by source total; repeated tabs must agree.
-- Existing APU/rubro links and -B variants are preserved. The ten source gaps remain stubs.
-- Imported input identity includes type, description, unit, and observed six-decimal tariff.

DELETE FROM apu_seccion s USING apu a, presupuesto p, proyecto pr
WHERE s.apu_id=a.id AND a.presupuesto_id=p.id AND p.proyecto_id=pr.id
 AND pr.nombre_proyecto='Cetro Médico Tulcán';

-- Import workbook inputs not already present in the CMT project base.
INSERT INTO insumo (public_id,base_id,codigo,tipo,descripcion,unidad,precio_unitario)
