 ('0192f6c4-7c8a-7abc-8000-000000902543'::uuid,'501DO8','MANO_OBRA',3,'Operador de equipo liviano (EO D2)',FALSE,1.000000,4.280000,4.280000,2.666000,'h',NULL,11.410480,'MANO_OBRA',4.280000)
) AS v(public_id,apu_codigo,seccion_tipo,orden,descripcion,es_hm,cantidad,tarifa_jornal,
 costo_hora,rendimiento,unidad,precio_unitario_tarifa,costo,insumo_tipo,insumo_precio)
JOIN apu a ON a.codigo=v.apu_codigo
 AND a.presupuesto_id=(SELECT p.id FROM presupuesto p JOIN proyecto pr ON pr.id=p.proyecto_id WHERE pr.nombre_proyecto='Cetro Médico Tulcán' AND p.version=1)
JOIN apu_seccion s ON s.apu_id=a.id AND s.tipo=v.seccion_tipo
LEFT JOIN LATERAL (
 SELECT i.id FROM insumo i
 WHERE i.base_id=(SELECT b.id FROM base_insumos b JOIN proyecto pr ON pr.id=b.proyecto_id WHERE pr.nombre_proyecto='Cetro Médico Tulcán' AND b.tipo='PROYECTO')
  AND i.tipo=v.insumo_tipo AND i.descripcion=v.descripcion AND i.unidad=v.unidad
 ORDER BY (i.precio_unitario=v.insumo_precio) DESC, i.id LIMIT 1
) input ON NOT v.es_hm;

